INSERT INTO MBTApp_sitephotos VALUES(1,'https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/e7c67178548f.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/42b91ab7c950.webp','/static/img/mbt/o-nas-2.jpg','/static/img/mbt/o-nas-zespol.jpg','/static/img/mbt/realizacja-eurosleeve.jpg','/static/img/bg/why-bg3-1.png','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/c4c3b74ce689.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/34754bbfa84c.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/65f5ac2e1b40.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/aaa9406ed7a3.webp','/static/img/mbt/o-nas-1.jpg','/static/img/mbt/Eurosleeve-10-scaled-fd8f7247.jpg','/static/img/mbt/IMG_20220722_102326-scaled-1-fdde92f8.jpg','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/edc93501919b.webp','/static/img/mbt/ZREALIZOWANE-ATT-1-scaled-f12dacac.jpg','/static/img/mbt/ZREALIZOWANE-ATT-3-scaled-b0f20287.jpg','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/ed7b48a494dc.webp','/static/img/mbt/ZREALIZOWANE-ATT-5-scaled-b27ef1aa.jpg','/static/img/mbt/ZREALIZOWANE-ATT-6-scaled-e17253f9.jpg','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/4b52bd6eff86.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/151dd278be86.webp','/static/img/mbt/Huber-6-scaled-b00b8b23.jpg','/static/img/mbt/3-2-scaled-38947c85.jpg','/static/img/mbt/breem-e659b8f2.jpg','/static/img/mbt/hala-1024x672-eb7144c9.jpg','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/205539665175.webp','/static/img/bg/header-1-bg.png','/static/img/bg/footer-bg1-1.png','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/374e7a5adfbf.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/media/uploads/0b5b6f5c26b1.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/media/uploads/ed67bb1b2b03.webp','https://pub-055b6d77c1e84acda77dbc29041f73ff.r2.dev/uploads/6f70f8a65c1f.webp','h