CREATE TABLE IF NOT EXISTS "MBTApp_job" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "slug" varchar(200) NOT NULL UNIQUE, "text" text NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "t_text" text NOT NULL CHECK ((JSON_VALID("t_text") OR "t_text" IS NULL)), "t_title" text NOT NULL CHECK ((JSON_VALID("t_title") OR "t_title" IS NULL)));
