CREATE TABLE IF NOT EXISTS "MBTApp_reference" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "firma" varchar(200) NOT NULL, "tresc" text NOT NULL, "osoba" varchar(200) NOT NULL, "stanowisko" varchar(200) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "t_osoba" text NOT NULL CHECK ((JSON_VALID("t_osoba") OR "t_osoba" IS NULL)), "t_stanowisko" text NOT NULL CHECK ((JSON_VALID("t_stanowisko") OR "t_stanowisko" IS NULL)), "t_tresc" text NOT NULL CHECK ((JSON_VALID("t_tresc") OR "t_tresc" IS NULL)));
