t_hours") OR "t_hours" IS NULL)), "t_hours_long" text NOT NULL CHECK ((JSON_VALID("t_hours_long") OR "t_hours_long" IS NULL)), "t_office_katowice" text NOT NULL CHECK ((JSON_VALID("t_office_katowice") OR "t_office_katowice" IS NULL)), "t_office_krakow" text NOT NULL CHECK ((JSON_VALID("t_office_krakow") OR "t_office_krakow" IS NULL)), "t_office_zabrze" text NOT NULL CHECK ((JSON_VALID("t_office_zabrze") OR "t_office_zabrze" IS NULL)), "t_tagline" text NOT NULL CHECK ((JSON_VALID("t_tagline") OR "t_tagline" IS NULL)), "office_site_gallery" text NOT NULL CHECK ((JSON_VALID("office_site_gallery") OR "office_site_gallery" IS NULL)), "hero_subtitle" varchar(200) NOT NULL, "hero_text" text NOT NULL, "hero_title1" varchar(200) NOT NULL, "hero_title2" varchar(200) NOT NULL, "t_hero_subtitle" text NOT NULL CHECK ((JSON_VALID("t_hero_subtitle") OR "t_hero_subtitle" IS NULL)), "t_hero_text" text NOT NULL CHECK ((JSON_VALID("t_hero_text") OR "t_hero_text" IS NULL)), "t_hero_title1" text NOT NULL CHECK ((JSON_VALID("t_hero_title1") OR "t_hero_title1" IS NULL)), "t_hero_title2" text NOT NULL CHECK ((JSON_VALID("t_hero_title2") OR "t_hero_title2" IS NULL)));
